import{_ as d}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as o,c as l,o as r,af as t,b as c,G as a,w as n,a as u,ag as h}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const A=JSON.parse('{"title":"Complexity Decision Ladder","description":"A six-rung decision table — requirement → lowest-complexity solution → upgrade trigger; read it before any protocol introduction, because protocols are options, not a learning order.","frontmatter":{"title":"Complexity Decision Ladder","description":"A six-rung decision table — requirement → lowest-complexity solution → upgrade trigger; read it before any protocol introduction, because protocols are options, not a learning order.","domain":"tech","tags":["tech","orientation","decision"],"navOrder":1,"topicId":"complexity-ladder","layer":"0","status":"canonical","nodeType":"pattern","owner":"learn-ai","externalOwners":[],"prerequisites":["tech-map"],"next":["site-boundaries"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/00-map/complexity-ladder.md","filePath":"tech/00-map/complexity-ladder.md","lastUpdated":1791169449000}'),p={name:"tech/00-map/complexity-ladder.md"};function g(m,e,f,b,y,w){const i=o("Mermaid"),s=o("LadderStepper");return r(),l("div",null,[e[1]||(e[1]=t('<blockquote><p><strong>Group</strong>: Map · Orientation and Boundaries | <strong>Previous group exit</strong>: none | <strong>This group exit</strong>: you can pick the lowest-complexity solution for any requirement and state its upgrade trigger <strong>Prerequisites</strong>: <a href="./../index.html">Tech Map</a> | <strong>Next</strong>: <a href="./site-boundaries.html">Site Boundaries and Knowledge Ownership</a>; to enter the Context group now, start with <a href="./../03-context/prompt.html">Prompt Engineering</a></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>Lead with the answer</strong>: for any AI requirement, find your rung on the ladder below, adopt that rung&#39;s <strong>lowest-complexity solution</strong>, and climb only when an explicit upgrade trigger fires. This table precedes any protocol introduction — MCP, A2A, ACP, and AG-UI are candidates for rung 6, not a learning order.</p><h3 id="mental-model-one-ladder" tabindex="-1">Mental model: one ladder <a class="header-anchor" href="#mental-model-one-ladder" aria-label="Permalink to &quot;Mental model: one ladder&quot;">​</a></h3>',4)),(r(),c(h,null,{default:n(()=>[a(i,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20BT%0A%20%20%20%20R1%5B%22Rung%201%3Cbr%2F%3EPrompt%20%2B%20structured%20output%22%5D%20--%3E%7Cneeds%20external%20facts%7C%20R2%5B%22Rung%202%3Cbr%2F%3ERetrieval%20%2F%20RAG%22%5D%0A%20%20%20%20R1%20--%3E%7Cneeds%20one%20action%7C%20R3%5B%22Rung%203%3Cbr%2F%3ETool%20calling%22%5D%0A%20%20%20%20R2%20--%3E%7Cneeds%20multi-step%20composition%7C%20R4%5B%22Rung%204%3Cbr%2F%3EWorkflow%22%5D%0A%20%20%20%20R3%20--%3E%7Cmulti-step%20%C2%B7%20recoverable%20%C2%B7%20approval%7C%20R4%0A%20%20%20%20R4%20--%3E%7Cautonomous%20loop%20%2B%20explicit%20stop%20condition%7C%20R5%5B%22Rung%205%3Cbr%2F%3EAgent%22%5D%0A%20%20%20%20R5%20--%3E%7Ccross-trust-domain%20%C2%B7%20async%20%C2%B7%20capability%20discovery%7C%20R6%5B%22Rung%206%3Cbr%2F%3EBoundary%20protocol%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[u(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>The ladder has one rule: <strong>default to the lowest rung and let evidence push you up.</strong> Every climb adds state, boundaries, and failure modes; every descent removes a class of trouble you have not met yet.</p><h3 id="the-six-rung-decision-table" tabindex="-1">The six-rung decision table <a class="header-anchor" href="#the-six-rung-decision-table" aria-label="Permalink to &quot;The six-rung decision table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rung</th><th>Requirement</th><th>Lowest-complexity solution</th><th>Upgrade trigger</th><th>Downgrade counterexample</th></tr></thead><tbody><tr><td>1</td><td>Fixed input → fixed output</td><td>Prompt + structured output</td><td>External facts or actions needed</td><td>If the answer fits in the prompt / context, do not build a retrieval pipeline</td></tr><tr><td>2</td><td>Needs external facts</td><td>Retrieval / RAG (Retrieval-Augmented Generation)</td><td>Many sources; permissions / updates / latency become the problem</td><td>With a small, stable knowledge set, inlining into context is cheaper</td></tr><tr><td>3</td><td>Needs one controlled action</td><td>Function call / tool calling</td><td>Multi-step, recoverable, approval-gated → rung 4</td><td>A single-step action needs no agent loop</td></tr><tr><td>4</td><td>Needs multi-step decisions</td><td>Workflow / same-domain subtasks</td><td>Autonomous loop with explicit stop conditions → rung 5</td><td>If steps can be enumerated statically, an autonomous loop only adds risk</td></tr><tr><td>5</td><td>Needs an autonomous loop</td><td>Agent (runtime + stop condition + permission boundary)</td><td>Cross-trust-domain, async tasks, capability discovery, cross-implementation interop</td><td>If the task completes inside one process, do not cross boundaries with protocols</td></tr><tr><td>6</td><td>Cross-process / org / trust domain</td><td>Protocol by connection direction (MCP / A2A / ACP / AG-UI)</td><td>— (top of ladder)</td><td>In-host tool access: a direct function or plain HTTP suffices</td></tr></tbody></table><h3 id="decision-comparison-what-each-rung-adds" tabindex="-1">Decision comparison (what each rung adds) <a class="header-anchor" href="#decision-comparison-what-each-rung-adds" aria-label="Permalink to &quot;Decision comparison (what each rung adds)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rung</th><th>Direction</th><th>Control</th><th>Added state</th><th>Trust domain</th><th>Lowest complexity</th></tr></thead><tbody><tr><td>1</td><td>Read</td><td>You write the prompt; changeable per call</td><td>none</td><td>in-process</td><td>prompt + output schema</td></tr><tr><td>2</td><td>Read</td><td>You control indexing and refresh</td><td>index + data freshness</td><td>data-source boundary</td><td>retrieval</td></tr><tr><td>3</td><td>Write (single)</td><td>function boundary + parameter validation</td><td>call results and side effects</td><td>in-process</td><td>tool calling</td></tr><tr><td>4</td><td>Write (multi)</td><td>orchestration; steps enumerable statically</td><td>multi-step state and intermediates</td><td>in-process</td><td>workflow</td></tr><tr><td>5</td><td>Read-write loop</td><td>stop condition + permission boundary</td><td>session / memory / checkpoints</td><td>within host</td><td>agent runtime</td></tr><tr><td>6</td><td>Read-write across boundaries</td><td>protocol negotiation + capability discovery</td><td>tasks / messages / artifacts</td><td>cross-trust-domain</td><td>boundary protocol</td></tr></tbody></table><p>&quot;Direction&quot; means read world (retrieval, citations — no side effects by default) versus write world (tools, actions — they change external state). Every write-world rung must explicitly handle permissions, idempotency, cancellation, retry, and rollback.</p><h3 id="when-to-use-when-not-to" tabindex="-1">When to use / when not to <a class="header-anchor" href="#when-to-use-when-not-to" aria-label="Permalink to &quot;When to use / when not to&quot;">​</a></h3><ul><li>Use: before implementation, in design reviews, and whenever judging &quot;should we adopt an agent / a protocol&quot;.</li><li>Do not use: for the concrete implementation once the rung is decided — go to the matching layer&#39;s five-part chapter.</li></ul><p>Historical milestones: this ladder was frozen in 2026-09 with Issue #116, merging the old &quot;training decision tree&quot; and the &quot;workflow vs agent&quot; discussions; earlier origins are unverified and will not be fabricated.</p><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><p>This page is a decision tool with no runnable code artifact; &quot;Usage&quot; = decision drills (pen and paper, ≤15 minutes). Acceptance: all four scenarios select the lowest-complexity solution and can say why a higher rung is not justified.</p><h3 id="drill-four-scenarios" tabindex="-1">Drill: four scenarios <a class="header-anchor" href="#drill-four-scenarios" aria-label="Permalink to &quot;Drill: four scenarios&quot;">​</a></h3><p>For each scenario, pick a rung yourself first, then compare with the expected output.</p><p><strong>Scenario A</strong>: classify support emails into three categories with a confidence score.</p><ul><li>Expected: rung 1. Fixed input → fixed output; prompt + output schema is enough.</li><li>Counterexample check: no external facts (no ticket lookup) and no actions (no status change), so no upgrade trigger fires.</li></ul><p><strong>Scenario B</strong>: answers must be grounded in 8,000 internal wiki pages.</p><ul><li>Expected: rung 2. External facts exceed the context budget; use retrieval / RAG.</li><li>Counterexample check: with only 20 pages updated quarterly, inlining into context (rung 1 + long context) is cheaper.</li></ul><p><strong>Scenario C</strong>: after user confirmation, file the expense report into the approval system.</p><ul><li>Expected: rung 3. One controlled action: tool call + parameter validation + permission boundary.</li><li>Counterexample check: the model is not deciding a &quot;check limit → write → notify&quot; chain; if it must, that is rung 4.</li></ul><p><strong>Scenario D</strong>: a research assistant reads literature, cross-checks, and writes a survey, deciding when to stop on its own.</p><ul><li>Expected: rung 5. An autonomous loop presumes you can write <strong>explicit stop conditions</strong> (page cap, time cap, verification passed) and <strong>permission boundaries</strong> (read-only sandbox).</li><li>Counterexample check: if the steps are really a fixed &quot;retrieve → summarize → aggregate&quot; chain, that is a rung-4 workflow, not autonomy.</li></ul><h3 id="boundaries-of-use" tabindex="-1">Boundaries of use <a class="header-anchor" href="#boundaries-of-use" aria-label="Permalink to &quot;Boundaries of use&quot;">​</a></h3><ul><li>The ladder decides the <strong>system shape</strong>, not model capability: the same model serves every rung.</li><li>Rungs can compose (an agent internally calls RAG), but the externally visible shape takes the highest rung involved, and the risk budget is assessed at that rung.</li></ul>',23)),a(s),e[3]||(e[3]=t('<h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><h3 id="why-default-to-the-lowest-rung" tabindex="-1">Why default to the lowest rung <a class="header-anchor" href="#why-default-to-the-lowest-rung" aria-label="Permalink to &quot;Why default to the lowest rung&quot;">​</a></h3><p>Each upgrade monotonically increases three kinds of cost:</p><ol><li><strong>State</strong>: rung 1 is stateless; rung 2 adds an index and freshness; rung 4 adds multi-step intermediates; rung 5 adds sessions, memory, and checkpoints. More state, costlier recovery and debugging.</li><li><strong>Boundaries</strong>: from in-process to the data-source boundary, then across trust domains. Every boundary adds a class of authorization, versioning, and protocol-negotiation problems.</li><li><strong>Failure modes</strong>: a rung-1 failure is &quot;output violates schema&quot;, retryable on the spot; a rung-5 failure may be &quot;three side effects already executed&quot;, requiring compensation and rollback.</li></ol><p>Low-rung failures are <strong>local and replayable</strong>; high-rung failures are <strong>distributed and side-effecting</strong>. Hence &quot;let evidence push you up&quot;: climbing without a fired trigger means pre-paying complexity for problems you do not have.</p><h3 id="read-world-write-world-as-a-cross-cutting-invariant" tabindex="-1">Read world / write world as a cross-cutting invariant <a class="header-anchor" href="#read-world-write-world-as-a-cross-cutting-invariant" aria-label="Permalink to &quot;Read world / write world as a cross-cutting invariant&quot;">​</a></h3><p>Rungs 1–2 mostly read the world: they supply evidence with no side effects by default. From rung 3 the system writes the world: it changes external state, so permissions, idempotency, cancellation, retry, human approval, and rollback must be handled explicitly. These are not rung-specific topics but questions every rung from 3 upward must answer — layers 4 and 5 return to this checklist repeatedly.</p><h3 id="why-protocols-sit-at-the-top" tabindex="-1">Why protocols sit at the top <a class="header-anchor" href="#why-protocols-sit-at-the-top" aria-label="Permalink to &quot;Why protocols sit at the top&quot;">​</a></h3><p>Protocols (rung 6) solve communication and capability discovery across trust domains. They add not just technical cost but organizational cost: version negotiation, security boundaries, interoperability commitments. Only when there is an independent trust domain, async tasks, capability discovery, or cross-implementation interop is a protocol the right option. In-host tool access needs only a direct function call or plain HTTP.</p><h3 id="specification-vs-local-measurement" tabindex="-1">Specification vs local measurement <a class="header-anchor" href="#specification-vs-local-measurement" aria-label="Permalink to &quot;Specification vs local measurement&quot;">​</a></h3><p>This page is a decision pattern with no specification to test against. &quot;Spec vs measurement&quot; columns for each rung&#39;s solution live in the matching layer chapters: structured output and model API (Inference &amp; Interface), RAG (Grounding), tool execution (Action), protocols (Interoperability).</p><h2 id="_4-development" tabindex="-1">4. Development <a class="header-anchor" href="#_4-development" aria-label="Permalink to &quot;4. Development&quot;">​</a></h2><p>This page has no code integration; &quot;Development&quot; = using the ladder as a design and review gate.</p><h3 id="symptom-→-evidence-→-action-→-done" tabindex="-1">Symptom → Evidence → Action → Done <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done&quot;">​</a></h3><p><strong>Symptom</strong>: the system fails randomly, is hard to debug, and nobody can name the components a single request passed through. <strong>Evidence</strong>: agent / protocol nodes appear in the architecture diagram while the requirement lands on rungs 1–3; traces show many loop steps unrelated to the task. <strong>Action</strong>: downgrade to the lowest rung that satisfies acceptance; record the removed capabilities as explicit TODOs pending real triggers. <strong>Done</strong>: the design doc states the current rung, the checked upgrade triggers, and evidence for any trigger that has fired.</p><h3 id="symptom-→-evidence-→-action-→-done-1" tabindex="-1">Symptom → Evidence → Action → Done <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-1" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done&quot;">​</a></h3><p><strong>Symptom</strong>: the team argues over &quot;should we go agent&quot; with no resolution. <strong>Evidence</strong>: neither side can write the autonomous loop&#39;s <strong>stop condition</strong> or <strong>permission boundary</strong> — empty fields mean rung 5&#39;s admission criteria are unmet. <strong>Action</strong>: implement as a rung-4 workflow first; collect cases where steps cannot be statically enumerated as upgrade evidence. <strong>Done</strong>: either the static step list runs (stay at rung 4), or real enumeration-failure cases accumulate before upgrading.</p><h3 id="symptom-→-evidence-→-action-→-done-2" tabindex="-1">Symptom → Evidence → Action → Done <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-2" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done&quot;">​</a></h3><p><strong>Symptom</strong>: a review demands MCP / A2A &quot;for future integration&quot;. <strong>Evidence</strong>: all collaboration today is inside one host / process; there is no second trust domain, no async task, no capability-discovery need. <strong>Action</strong>: check each rung-6 upgrade trigger; with none fired, use an in-process solution. <strong>Done</strong>: the design doc states &quot;if X appears later (cross-trust-domain / async / capability discovery), then introduce protocol Y&quot;.</p><h3 id="anti-pattern-list" tabindex="-1">Anti-pattern list <a class="header-anchor" href="#anti-pattern-list" aria-label="Permalink to &quot;Anti-pattern list&quot;">​</a></h3><ul><li><strong>Noun-driven architecture</strong>: pick a trending protocol / framework first, then hunt for a scene that justifies it.</li><li><strong>Level skipping</strong>: jump to agents while skipping output schemas and failure acceptance (the rung-1 homework) — every upper-layer fault collapses into &quot;the model is bad&quot;.</li><li><strong>Demo as acceptance</strong>: a working demo ≠ existing stop conditions, permission boundaries, and rollback paths. This is the classic &quot;looks successful but under-evidenced&quot; path.</li></ul><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><p>Four-level reading route:</p><ul><li><strong>Beginner</strong>: this page + the <a href="./../index.html">Tech Map</a> decision tree; recite the six rungs and their triggers.</li><li><strong>Builder</strong>: enter the <a href="./../03-context/">Context group</a> and make rung 1 solid (prompt + schema + failure acceptance).</li><li><strong>Operator</strong>: enter the <a href="./../06-agent-systems/agent-runtime.html">Agent Systems group</a> and the <a href="./../08-production/">Production group</a> for permissions, idempotency, and rollback at rungs 3–5.</li><li><strong>Researcher</strong>: read the L1 resources below on the workflow-vs-agent boundary argument.</li></ul><h3 id="resource-table" tabindex="-1">Resource table <a class="header-anchor" href="#resource-table" aria-label="Permalink to &quot;Resource table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Evidence level</th><th>Canonical URL</th><th>Purpose</th><th>Supported claim</th><th>Next</th></tr></thead><tbody><tr><td>Building Effective Agents (Anthropic)</td><td>L1 (maintainer)</td><td><a href="https://www.anthropic.com/research/building-effective-agents" target="_blank" rel="noreferrer">https://www.anthropic.com/research/building-effective-agents</a></td><td>The workflow / agent boundary; the case for starting with compositions</td><td>The &quot;compose first, escalate later&quot; engineering position (retrievedAt 2026-09-01, HTTP 200)</td><td>Compare with rungs 4 / 5 here</td></tr><tr><td>MCP official site</td><td>L0 (official spec)</td><td><a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/</a></td><td>One rung-6 candidate: the agent ↔ tools / data boundary</td><td>Protocols solve boundary communication (retrievedAt 2026-09-01, HTTP 200)</td><td><a href="./../07-interoperability/mcp.html">MCP chapter</a></td></tr><tr><td>A2A official site</td><td>L0 (official spec)</td><td><a href="https://a2a-protocol.org/" target="_blank" rel="noreferrer">https://a2a-protocol.org/</a></td><td>One rung-6 candidate: cross-trust-domain agent collaboration</td><td>Remote collaboration protocols presume cross-trust-domain needs (retrievedAt 2026-09-01, HTTP 200)</td><td><a href="./../07-interoperability/a2a.html">A2A chapter</a></td></tr><tr><td>Learn LLM chapter 11 (RAG)</td><td>sibling</td><td><a href="https://llm.zenheart.site/chapters/11-rag" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/11-rag</a></td><td>Deep principles behind rung 2 (when retrieval works)</td><td>Retrieval internals belong to Learn LLM (retrievedAt 2026-09-01, HTTP 200)</td><td>This repo&#39;s <a href="./../04-grounding/">Grounding group</a></td></tr></tbody></table><h3 id="active-falsification-and-open-questions" tabindex="-1">Active falsification and open questions <a class="header-anchor" href="#active-falsification-and-open-questions" aria-label="Permalink to &quot;Active falsification and open questions&quot;">​</a></h3><ul><li>Falsification entry: if you find a scenario where rung N&#39;s lowest solution cannot pass acceptance while rung N-1&#39;s triggers have not fired, the ladder has a hole — revise the triggers instead of hiding the scenario.</li><li>Open: the rung-6 &quot;choose protocol by connection direction&quot; specifics (which boundary fits MCP / A2A / ACP / AG-UI) land in the layer-4 protocol map; this page keeps only the decision frame.</li></ul><h3 id="where-learn-ai-stops-where-to-continue" tabindex="-1">Where learn-ai stops / where to continue <a class="header-anchor" href="#where-learn-ai-stops-where-to-continue" aria-label="Permalink to &quot;Where learn-ai stops / where to continue&quot;">​</a></h3><ul><li>Implementation per rung: this repo&#39;s group chapters.</li><li>Deep principles for rungs 2 / 5 (retrieval math, how training shapes behavior): <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>.</li><li>Methods proving each rung is &quot;done&quot;: <a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>.</li></ul>',30))])}const _=d(p,[["render",g]]);export{A as __pageData,_ as default};
